refs=[]
def ref(key,author,title,year,url,locator,scope='full text: cited result read',doi=None,verified=True,extra=None):
    r=dict(key='AG45-'+key,author=author,title=title,year=str(year),url=url,locator=locator,verification_scope=scope,note='verified' if verified else 'unverified',checked='2026-11-19')
    if doi:r['doi']=doi
    if extra:r.update(extra)
    refs.append(r)
