lines=[]
for r in refs:
    lines.append('@misc{'+r['key']+',')
    for k in ['author','title','year','journal','volume','number','series','pages','publisher','howpublished','doi','url','note']:
        if k in r:lines.append('  '+k+' = {'+r[k]+'},')
    lines.append('  annote = {'+r['verification_scope']+'; locator: '+r['locator']+'; checked '+r['checked']+'}\n}\n')
(OUT/'references.bib').write_text('\n'.join(lines))
(OUT/'outputs/reference_verification.json').write_text(json.dumps(refs,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'references':len(refs),'verified':sum(r['note']=='verified' for r in refs),'unverified':[r['key'] for r in refs if r['note']=='unverified']}))
